// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 value, uint256 extra) public {
        value = bound(value, 1, 1e30);
        extra = bound(extra, 1, 1e30);
        uint256 total = value + extra;
        // contract holds strictly more than the requested amount
        vm.deal(address(c), total);
        vm.prank(address(this));
        c.withdraw(value);
        // after withdrawing exactly `value`, the contract retains exactly total - value
        assertTrue(address(c).balance == total - value);
    }
}
